BEGIN;
INSERT INTO pricing_catalogues (id, catalogue, published) VALUES ('default', '{"plans": [{"id": "tier_free", "tier": "free", "name": "Free", "subtitle": "For individuals exploring quantitative markets & charting", "monthly_amount": 0.0, "annual_monthly_amount": 0.0, "currency_symbol": "₹", "features_summary": ["Up to 100 quantitative journal logs", "Standard NSE / BSE candlestick charting", "Basic technical indicators (RSI, MACD, EMA)", "Community social feed & strategy sharing", "1 Custom Watchlist (up to 20 instruments)", "20 AI copilot queries / month", "Standard end-of-day market data feed", "Community forum & public knowledgebase"], "badge_label": null, "highlighted": false, "is_current": false, "cta_label": "Continue with Free"}, {"id": "tier_pro", "tier": "premium", "name": "Pro", "subtitle": "For active traders & quants scaling their market edge", "monthly_amount": 2499.0, "annual_monthly_amount": 1999.0, "currency_symbol": "₹", "features_summary": ["Unlimited quantitative journal entries", "Auto-screenshot chart capture & auto-fill", "AI Trade Assistant & Chart Vision recognition", "Real-time Level 2 multi-timeframe scanner", "Equity curve analytics & Sharpe drawdown", "Unlimited watchlists with real-time alerts", "Strategy backtester & version history logs", "500 AI copilot queries / month", "Priority email & dedicated trader support"], "badge_label": "MOST POPULAR", "highlighted": true, "is_current": false, "cta_label": "Choose Pro"}, {"id": "tier_enterprise", "tier": "enterprise", "name": "Enterprise", "subtitle": "For prop trading desks, funds & institutional teams", "monthly_amount": 7999.0, "annual_monthly_amount": 6499.0, "currency_symbol": "₹", "features_summary": ["Everything in Pro, plus:", "10 Desk seats with granular role controls", "Desk-wide daily loss guardrails & hard stops", "Low-latency dedicated VPS gateway & bridges", "REST & FIX Webhook API for automated orders", "Custom AI model fine-tuning on playbooks", "5,000 AI copilot requests / month", "Institutional audit trail & CSV/PDF export", "Dedicated account manager & 99.9% uptime SLA"], "badge_label": null, "highlighted": false, "is_current": false, "cta_label": "Choose Enterprise"}], "categories": [{"id": "cat_trading", "name": "Core Trading & Analysis", "rows": [{"id": "feat_data_feed", "title": "Indian Market Data Feed (NSE / BSE / MCX)", "tooltip": "Live tick-by-tick real-time quotes and depth.", "free_value": "15m Delayed", "pro_value": "Real-time Tick", "enterprise_value": "Ultra-low Latency VPS", "is_boolean": false}, {"id": "feat_chart_layouts", "title": "Multi-Timeframe Chart Layouts", "tooltip": "Simultaneous synchronized chart panels per workspace.", "free_value": "1 Chart", "pro_value": "Up to 8 Charts", "enterprise_value": "Unlimited Multi-Monitor", "is_boolean": false}, {"id": "feat_indicators", "title": "Technical Indicators & Pine Scripts", "tooltip": "Access to custom indicators, overlays, and quant tools.", "free_value": "15 Basic", "pro_value": "100+ Indicators & Custom Scripts", "enterprise_value": "Full Quant Library & Pine Engine", "is_boolean": false}, {"id": "feat_scanners", "title": "Live Market Screener & Scanner", "tooltip": "Screening for breakouts, momentum, and volume surges.", "free_value": "Top 20 Gainers/Losers", "pro_value": "Live Multi-Filter Scanner", "enterprise_value": "Continuous Algorithmic Scanner", "is_boolean": false}]}, {"id": "cat_journaling", "name": "Quantitative Journaling & Backtesting", "rows": [{"id": "feat_journal_logs", "title": "Monthly Journal Entries", "tooltip": "Maximum trade executions logged per month.", "free_value": "100 entries / mo", "pro_value": "Unlimited", "enterprise_value": "Unlimited Multi-Trader", "is_boolean": false}, {"id": "feat_screenshot_sync", "title": "Chart Screenshot Auto-Capture", "tooltip": "Automatically binds broker execution charts to journals.", "free_value": false, "pro_value": true, "enterprise_value": true, "is_boolean": true}, {"id": "feat_analytics", "title": "Equity Curve & Risk Statistics (Sharpe, Drawdown)", "tooltip": "Calculates performance metrics, win rates, and R-multiples.", "free_value": "Basic PnL", "pro_value": "Full Quant Analytics", "enterprise_value": "Desk Exposure & VaR Analytics", "is_boolean": false}, {"id": "feat_backtest", "title": "Strategy Backtester & Version History", "tooltip": "Simulate playbooks across historical price datasets.", "free_value": "1 Playbook", "pro_value": "Unlimited Backtests", "enterprise_value": "Walk-Forward Optimization Engine", "is_boolean": false}, {"id": "feat_export", "title": "Tax & Compliance CSV / PDF Export", "tooltip": "Download audit-ready trade execution and PnL sheets.", "free_value": false, "pro_value": true, "enterprise_value": true, "is_boolean": true}]}, {"id": "cat_ai", "name": "AI Copilot & Market Intelligence", "rows": [{"id": "feat_ai_queries", "title": "Monthly AI Copilot Queries", "tooltip": "AI chart pattern, sentiment, and setup analysis queries.", "free_value": "20 queries / mo", "pro_value": "500 queries / mo", "enterprise_value": "5,000 queries / mo", "is_boolean": false}, {"id": "feat_vision_pattern", "title": "Chart Vision Pattern Recognition", "tooltip": "Detects flags, double tops, orderblocks, and fair value gaps.", "free_value": false, "pro_value": true, "enterprise_value": true, "is_boolean": true}, {"id": "feat_sentiment", "title": "Real-Time Macro News Sentiment Engine", "tooltip": "Instant sentiment score for RBI decisions, earnings, and news.", "free_value": "Headline Feed", "pro_value": "Real-time Sentiment Scoring", "enterprise_value": "High-Frequency Sentiment API", "is_boolean": false}]}, {"id": "cat_desk", "name": "Desk Governance, Risk & Support", "rows": [{"id": "feat_seats", "title": "Team Seats & Organization Roster", "tooltip": "Included seats with role-based permission hierarchy.", "free_value": "1 Trader", "pro_value": "1 Trader", "enterprise_value": "10 Seats Included (Add more)", "is_boolean": false}, {"id": "feat_risk_guards", "title": "Prop Desk Hard Risk Stops & Daily Loss Caps", "tooltip": "Automated circuit breaker halts trading on limit breach.", "free_value": false, "pro_value": "Alerts Only", "enterprise_value": "Automated Broker Hard Stop", "is_boolean": false}, {"id": "feat_api_access", "title": "REST, WebSocket & FIX Webhooks", "tooltip": "Automated programmatic execution and data extraction.", "free_value": false, "pro_value": "Read-only API", "enterprise_value": "Full Read & Write Webhooks", "is_boolean": false}, {"id": "feat_support", "title": "Customer & Technical Support SLA", "tooltip": "Direct access to market specialists and quant team.", "free_value": "Community Forum", "pro_value": "Priority Chat & Email", "enterprise_value": "Dedicated Account Manager (99.9% SLA)", "is_boolean": false}]}], "faqs": [{"id": "faq_1", "category": "billing", "question": "Can I change or cancel my plan at any time?", "answer": "Yes. You can upgrade, downgrade, or cancel your subscription at any time directly from Account Settings. If you cancel, you will maintain full access through the end of your prepaid billing period."}, {"id": "faq_2", "category": "billing", "question": "Are prices in Indian Rupees (INR) and do they include GST?", "answer": "All prices are listed in Indian Rupees (INR ₹). At checkout, standard 18% Indian GST is itemized transparently with tax invoices provided for business input tax credit (ITC)."}, {"id": "faq_3", "category": "billing", "question": "What payment methods do you accept?", "answer": "We accept UPI (Google Pay, PhonePe, Paytm), all major Indian Credit and Debit Cards (Visa, Mastercard, RuPay), Net Banking across 50+ Indian banks, and international cards via Stripe/Razorpay."}, {"id": "faq_4", "category": "features", "question": "How does the AI Trading Copilot work?", "answer": "TradeX AI evaluates chart images, technical indicator states, and market structure using neural vision models. It highlights high-probability risk-to-reward invalidation levels and detects complex pattern formations."}, {"id": "faq_5", "category": "features", "question": "Can I connect my existing Indian broker account?", "answer": "Yes. TradeX supports direct auto-sync integration with major Indian brokers including Zerodha Kite, Upstox, Angel One, Dhan, and Groww for automated journal logging and order execution."}, {"id": "faq_6", "category": "enterprise", "question": "What is included in the Enterprise plan for prop desks?", "answer": "Enterprise provides multi-seat manager dashboards, desk-wide daily loss limits, low-latency dedicated VPS connectivity, audit logs, and custom webhook API access for automated algorithmic systems."}], "annual_discount_percent": 20, "annual_months_billed": 12, "footer_disclaimer": "Prices in INR (₹). Standard 18% GST itemized transparently at checkout. Cancel anytime.", "copy": {"badge": "Plans for every workspace", "title": "Choose Your Trading Plan", "description": "Compare tools, data limits, and support for your trading workspace.", "monthly": "Monthly", "annual": "Billed annually", "current": "Current Plan", "processing": "Processing…", "matrix": "Compare Features Across Plans", "faq": "Frequently Asked Questions", "all": "All Questions", "retry": "Try again", "back": "Back", "error": "Unable to load pricing", "billing_suffix": "/month", "annual_savings": "saved with annual billing", "feature": "Feature"}}'::jsonb, true) ON CONFLICT (id) DO UPDATE SET catalogue = EXCLUDED.catalogue, published = EXCLUDED.published;
INSERT INTO public_site_pages (id, content, published) VALUES ('landing', '{"brand": "TradeX", "title": "The Foundation for your Trading System", "description": "AI analysis, quantitative journaling, market intelligence, and community in one workspace. Built for precision, clarity, and disciplined execution.", "signin_label": "Sign in", "start_label": "Get Started Free", "pricing_label": "Explore Plans", "features_title": "Tools for Every Trading Decision", "roles_title": "Choose Your Workspace", "pricing_title": "Plans for Your Trading Workspace", "faq_title": "Frequently Asked Questions", "footer": "TradeX · A workspace for disciplined traders. Market information is provided for research; it is not investment advice.", "retry_label": "Try again", "error_title": "Unable to load page content", "features": [{"title": "Institutional Community", "description": "Share setups, discuss markets, and follow traders across a curated community.", "icon": "forum"}, {"title": "Quantitative Journaling", "description": "Record execution, review equity curves, and connect notes with your trading playbooks.", "icon": "book"}, {"title": "Market Intelligence", "description": "Browse market news, instrument snapshots, price history, and company fundamentals.", "icon": "news"}, {"title": "AI Trading Assistant", "description": "Review charts and trading ideas with context from your workspace.", "icon": "ai"}], "roles": [{"id": "customer", "title": "Trader", "description": "Build discipline with journals, strategies, notes, and a trading community.", "cta": "Get Started as Trader"}, {"id": "affiliate", "title": "Affiliate", "description": "Grow your audience with referral links, campaign tracking, and transparent commissions.", "cta": "Apply as Affiliate"}], "faqs": [{"id": "landing_records", "category": "features", "question": "How do notes, journals, and strategies connect?", "answer": "Link your private writing records and selectively publish individual records to the community."}, {"id": "landing_roles", "category": "general", "question": "Who can join TradeX?", "answer": "Traders can create a trading workspace. Affiliates can apply for a partner workspace."}]}'::jsonb, true) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, published = EXCLUDED.published;
COMMIT;
